const crypto = require('crypto');

const REPLAY_WINDOW_SEC = 300;
const RATE_LIMIT_PER_MIN = 30;
const ALLOWED_RISKS = new Set(['READ']);

const REGISTRY = {
  'system.status': {
    description: 'Estado geral do OMEAB (CPU/RAM/uptime/load).',
    risk: 'READ',
    enabled: true,
    requires_confirmation: false,
    parameter_schema: { type: 'object', additionalProperties: false, properties: {} },
    executor: 'system.status',
    timeout_ms: 10000,
    audit: true,
  },
  'storage.status': {
    description: 'Estado do volume /srv/storage.',
    risk: 'READ',
    enabled: true,
    requires_confirmation: false,
    parameter_schema: { type: 'object', additionalProperties: false, properties: {} },
    executor: 'storage.status',
    timeout_ms: 10000,
    audit: true,
  },
  'backup.status': {
    description: 'Estado compacto dos backups (sem iniciar backup).',
    risk: 'READ',
    enabled: true,
    requires_confirmation: false,
    parameter_schema: { type: 'object', additionalProperties: false, properties: {} },
    executor: 'backup.status',
    timeout_ms: 10000,
    audit: true,
  },
  'docker.status': {
    description: 'Estado READ-ONLY dos containers Docker.',
    risk: 'READ',
    enabled: true,
    requires_confirmation: false,
    parameter_schema: { type: 'object', additionalProperties: false, properties: {} },
    executor: 'docker.status',
    timeout_ms: 10000,
    audit: true,
  },
  'disk.status': {
    description: 'Uso agregado dos mounts monitorados.',
    risk: 'READ',
    enabled: true,
    requires_confirmation: false,
    parameter_schema: { type: 'object', additionalProperties: false, properties: {} },
    executor: 'disk.status',
    timeout_ms: 10000,
    audit: true,
  },
  'immich.status': {
    description: 'Snapshot operacional Immich (sem fotos/faces/GPS).',
    risk: 'READ',
    enabled: true,
    requires_confirmation: false,
    parameter_schema: { type: 'object', additionalProperties: false, properties: {} },
    executor: 'immich.status',
    timeout_ms: 10000,
    audit: true,
  },
  'rag.stats': {
    description: 'Estatísticas agregadas do omeab-rag (sem conteúdo).',
    risk: 'READ',
    enabled: true,
    requires_confirmation: false,
    parameter_schema: { type: 'object', additionalProperties: false, properties: {} },
    executor: 'rag.stats',
    timeout_ms: 10000,
    audit: true,
  },
  'audiobook.stats': {
    description: 'Contadores agregados do audiobook-factory.',
    risk: 'READ',
    enabled: true,
    requires_confirmation: false,
    parameter_schema: { type: 'object', additionalProperties: false, properties: {} },
    executor: 'audiobook.stats',
    timeout_ms: 10000,
    audit: true,
  },
  'media.stats': {
    description: 'Métricas agregadas do omeab-media-manager.',
    risk: 'READ',
    enabled: true,
    requires_confirmation: false,
    parameter_schema: { type: 'object', additionalProperties: false, properties: {} },
    executor: 'media.stats',
    timeout_ms: 10000,
    audit: true,
  },
};

const FORBIDDEN_PARAM_KEYS = new Set([
  'url', 'host', 'port', 'protocol', 'command', 'shell', 'sql', 'query',
  'path', 'script', 'exec', 'docker', 'ssh', 'rm', 'compose', 'endpoint',
]);

const UUID_RE = /^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$/i;
const startedMs = Date.now();
const receivedAt = new Date().toISOString();

const item = $('Webhook').first();
const headersIn = item.json.headers || {};
const headers = {};
for (const [k, v] of Object.entries(headersIn)) {
  headers[String(k).toLowerCase()] = v;
}

let rawBody = '';
try {
  if (item.binary && item.binary.data && item.binary.data.data) {
    rawBody = Buffer.from(item.binary.data.data, 'base64').toString('utf8');
  }
} catch (e) {
  rawBody = '';
}

let body = {};
if (rawBody) {
  try {
    body = JSON.parse(rawBody);
  } catch (e) {
    body = null;
  }
} else {
  body = item.json.body ?? item.json;
  rawBody = JSON.stringify(body ?? {});
}

function reject(httpStatus, errorCode, message, extra = {}) {
  const requestId = (body && typeof body === 'object' && body.request_id) ? String(body.request_id) : null;
  const action = (body && typeof body === 'object' && body.action) ? String(body.action) : 'unknown';
  const securityCodes = new Set([
    'INVALID_SIGNATURE', 'REQUEST_EXPIRED', 'REPLAY_DETECTED',
    'ACTION_NOT_ALLOWED', 'INVALID_PARAMETERS', 'RATE_LIMITED',
  ]);
  const response = {
    request_id: requestId,
    action,
    status: 'rejected',
    executed: false,
    requires_confirmation: false,
    message,
    data: {},
    error_code: errorCode,
    started_at: new Date(startedMs).toISOString(),
    finished_at: new Date().toISOString(),
    ...extra,
  };
  return [{
    json: {
      gate: 'reject',
      http_status: httpStatus,
      security_event: securityCodes.has(errorCode),
      security_event_name: errorCode.toLowerCase(),
      audit: {
        request_id: requestId,
        requested_at: body && body.requested_at ? String(body.requested_at) : null,
        requested_by: body && body.requested_by ? String(body.requested_by).slice(0, 100) : null,
        action: action.slice(0, 150),
        risk: 'READ',
        parameters: {},
        status: 'rejected',
        executed: false,
        requires_confirmation: false,
        result_summary: { error_code: errorCode },
        error_code: errorCode,
        duration_ms: Date.now() - startedMs,
        received_at: receivedAt,
      },
      response,
      registry_action: null,
    },
  }];
}

const secret = $env.HESTIA_ACTION_SECRET;
if (!secret) {
  return reject(500, 'ROUTER_MISCONFIGURED', 'Action Router secret unavailable.');
}

if (body === null || typeof body !== 'object' || Array.isArray(body)) {
  return reject(400, 'INVALID_CONTRACT', 'Body JSON inválido.');
}

const tsHeader = headers['x-hestia-action-timestamp'];
const sigHeader = headers['x-hestia-action-signature'];
if (!tsHeader || !sigHeader) {
  return reject(401, 'INVALID_SIGNATURE', 'Assinatura ou timestamp ausente.');
}

const tsNum = Number(tsHeader);
if (!Number.isFinite(tsNum) || !/^\d+$/.test(String(tsHeader))) {
  return reject(401, 'INVALID_SIGNATURE', 'Timestamp inválido.');
}

const nowSec = Math.floor(Date.now() / 1000);
if (Math.abs(nowSec - tsNum) > REPLAY_WINDOW_SEC) {
  return reject(401, 'REQUEST_EXPIRED', 'Timestamp fora da janela de replay.');
}

const canonical = `${String(tsHeader)}.${rawBody}`;
const expected = crypto.createHmac('sha256', secret).update(canonical, 'utf8').digest('hex');
const provided = String(sigHeader).toLowerCase().trim();
const a = Buffer.from(expected, 'utf8');
const b = Buffer.from(provided, 'utf8');
if (a.length !== b.length || !crypto.timingSafeEqual(a, b)) {
  return reject(401, 'INVALID_SIGNATURE', 'Assinatura HMAC inválida.');
}

// Rate limit from previous node
let recentCount = 0;
try {
  const rateRows = $('Rate Limit Check').all().map((i) => i.json);
  const row = rateRows.find((r) => r.recent_count != null) || rateRows[0] || {};
  recentCount = Number(row.recent_count || 0);
} catch (e) {
  recentCount = 0;
}
if (recentCount >= RATE_LIMIT_PER_MIN) {
  return reject(429, 'RATE_LIMITED', 'Limite de requisições excedido.');
}

const version = String(body.version || '');
if (version !== '1.0') {
  return reject(400, 'INVALID_CONTRACT', 'version deve ser "1.0".');
}

const requestId = String(body.request_id || '');
if (!UUID_RE.test(requestId)) {
  return reject(400, 'INVALID_CONTRACT', 'request_id UUID inválido.');
}

if (!body.requested_at || Number.isNaN(Date.parse(String(body.requested_at)))) {
  return reject(400, 'INVALID_CONTRACT', 'requested_at inválido.');
}

const action = String(body.action || '');
if (!action || action.length > 100) {
  return reject(400, 'INVALID_CONTRACT', 'action inválida.');
}

const parameters = body.parameters;
if (parameters === undefined || parameters === null) {
  return reject(400, 'INVALID_PARAMETERS', 'parameters obrigatório (objeto, pode ser vazio).');
}
if (typeof parameters !== 'object' || Array.isArray(parameters)) {
  return reject(400, 'INVALID_PARAMETERS', 'parameters deve ser objeto.');
}

for (const key of Object.keys(parameters)) {
  if (FORBIDDEN_PARAM_KEYS.has(String(key).toLowerCase())) {
    return reject(400, 'INVALID_PARAMETERS', `Parâmetro proibido: ${key}`);
  }
}

const meta = REGISTRY[action];
if (!meta) {
  return reject(403, 'ACTION_NOT_ALLOWED', 'Action não permitida.');
}
if (!meta.enabled) {
  return reject(403, 'ACTION_NOT_ALLOWED', 'Action desabilitada.');
}
if (!ALLOWED_RISKS.has(meta.risk)) {
  return reject(403, 'ACTION_NOT_ALLOWED', 'Risk level não autorizado nesta versão.');
}

const paramKeys = Object.keys(parameters);
if (paramKeys.length > 0) {
  // V1: todas as actions READ exigem parameters vazios
  return reject(400, 'INVALID_PARAMETERS', 'Esta action não aceita parameters.');
}

if (meta.requires_confirmation) {
  const confirmationId = crypto.randomUUID();
  const expiresAt = new Date(Date.now() + 5 * 60 * 1000).toISOString();
  const paramsHash = crypto.createHash('sha256').update(JSON.stringify(parameters)).digest('hex');
  const response = {
    request_id: requestId,
    action,
    status: 'confirmation_required',
    executed: false,
    requires_confirmation: true,
    confirmation_id: confirmationId,
    expires_at: expiresAt,
    message: 'Confirmação necessária antes da execução.',
    data: {
      action,
      parameters_hash: paramsHash,
      risk: meta.risk,
    },
    started_at: new Date(startedMs).toISOString(),
    finished_at: new Date().toISOString(),
  };
  return [{
    json: {
      gate: 'confirm',
      http_status: 202,
      security_event: false,
      audit: {
        request_id: requestId,
        requested_at: String(body.requested_at),
        requested_by: String(body.requested_by || 'unknown').slice(0, 100),
        action,
        risk: meta.risk,
        parameters: {},
        status: 'confirmation_required',
        executed: false,
        requires_confirmation: true,
        result_summary: { confirmation_id: confirmationId, expires_at: expiresAt, parameters_hash: paramsHash },
        error_code: null,
        duration_ms: Date.now() - startedMs,
        received_at: receivedAt,
      },
      response,
      registry_action: action,
    },
  }];
}

return [{
  json: {
    gate: 'execute',
    http_status: 200,
    security_event: false,
    registry_action: action,
    executor: meta.executor,
    risk: meta.risk,
    timeout_ms: meta.timeout_ms,
    request_id: requestId,
    requested_at: String(body.requested_at),
    requested_by: String(body.requested_by || 'unknown').slice(0, 100),
    parameters: {},
    received_at: receivedAt,
    started_ms: startedMs,
    // SQL-safe literals for subsequent Postgres nodes
    sql_request_id: requestId,
    sql_requested_at: String(body.requested_at).replace(/'/g, "''"),
    sql_requested_by: String(body.requested_by || 'unknown').slice(0, 100).replace(/'/g, "''"),
    sql_action: action.replace(/'/g, "''"),
    sql_risk: meta.risk.replace(/'/g, "''"),
  },
}];

