(() => {
  const auth = $('Auth Validate Policy').first().json;
  const a = auth.audit || {};
  if (auth.skip_audit_insert) {
    return `SELECT 1 AS skipped_replay_audit;`;
  }
  const rid = String(a.request_id || '').replace(/'/g, "''");
  if (!rid || !/^[0-9a-fA-F-]{36}$/.test(rid)) {
    return `SELECT 1 AS skipped_no_request_id;`;
  }
  const action = String(a.action || 'unknown').replace(/'/g, "''").slice(0, 150);
  const risk = String(a.risk || 'READ').replace(/'/g, "''");
  const status = String(a.status || 'rejected').replace(/'/g, "''");
  const err = a.error_code ? String(a.error_code).replace(/'/g, "''") : null;
  const requestedBy = a.requested_by ? String(a.requested_by).replace(/'/g, "''") : null;
  const requestedAt = a.requested_at ? String(a.requested_at).replace(/'/g, "''") : null;
  const receivedAt = a.received_at ? String(a.received_at).replace(/'/g, "''") : null;
  const params = JSON.stringify(a.parameters || {}).replace(/'/g, "''");
  const summary = JSON.stringify(a.result_summary || {}).replace(/'/g, "''");
  const duration = Number.isFinite(Number(a.duration_ms)) ? Number(a.duration_ms) : 'NULL';
  const executed = a.executed ? 'true' : 'false';
  const conf = a.requires_confirmation ? 'true' : 'false';
  return `
INSERT INTO hestia_action_audit (
  request_id, requested_at, received_at, requested_by, action, risk, parameters,
  status, executed, requires_confirmation, result_summary, error_code, duration_ms
) VALUES (
  '${rid}'::uuid,
  ${requestedAt ? `'${requestedAt}'::timestamptz` : 'NULL'},
  ${receivedAt ? `'${receivedAt}'::timestamptz` : 'now()'},
  ${requestedBy ? `'${requestedBy}'` : 'NULL'},
  '${action}',
  '${risk}',
  '${params}'::jsonb,
  '${status}',
  ${executed},
  ${conf},
  '${summary}'::jsonb,
  ${err ? `'${err}'` : 'NULL'},
  ${duration}
)
ON CONFLICT (request_id) DO UPDATE SET
  status = EXCLUDED.status,
  executed = EXCLUDED.executed,
  result_summary = EXCLUDED.result_summary,
  error_code = EXCLUDED.error_code,
  duration_ms = EXCLUDED.duration_ms;
`;
})()
}}

