const ctx = $('Auth Validate Policy').first().json;
const rows = $input.all().map((i) => i.json).filter(Boolean);
const inserted = rows.find((r) => r && (r.id != null || r.inserted === true || r.request_id));

const ok = !!(inserted && (inserted.id != null || inserted.inserted === true));

if (!ok) {
  const startedMs = Number(ctx.started_ms || Date.now());
  const response = {
    request_id: ctx.request_id,
    action: ctx.registry_action,
    status: 'rejected',
    executed: false,
    requires_confirmation: false,
    message: 'Replay detectado.',
    data: {},
    error_code: 'REPLAY_DETECTED',
    started_at: new Date(startedMs).toISOString(),
    finished_at: new Date().toISOString(),
  };
  return [{
    json: {
      gate: 'reject',
      http_status: 409,
      security_event: true,
      security_event_name: 'replay_detected',
      skip_audit_insert: true,
      audit: {
        request_id: ctx.request_id,
        action: ctx.registry_action,
        status: 'rejected',
        executed: false,
        error_code: 'REPLAY_DETECTED',
        duration_ms: Date.now() - startedMs,
      },
      response,
    },
  }];
}

return [{
  json: {
    ...ctx,
    gate: 'execute',
    audit_reserved: true,
    reserved_id: inserted.id ?? null,
  },
}];

const startedMs = Number($('Auth Validate Policy').first().json.started_ms || Date.now());
const ctx = $('Auth Validate Policy').first().json;
const action = ctx.registry_action;
const requestId = ctx.request_id;
const executorItem = $input.first().json || {};

function fail(errorCode, message, partialData = {}) {
  const finished = new Date().toISOString();
  const response = {
    request_id: requestId,
    action,
    status: 'failed',
    executed: false,
    requires_confirmation: false,
    message,
    data: partialData,
    error_code: errorCode,
    started_at: new Date(startedMs).toISOString(),
    finished_at: finished,
  };
  return [{
    json: {
      http_status: errorCode === 'EXECUTOR_TIMEOUT' ? 504 : 502,
      security_event: false,
      audit: {
        request_id: requestId,
        requested_at: ctx.requested_at,
        requested_by: ctx.requested_by,
        action,
        risk: ctx.risk || 'READ',
        parameters: {},
        status: 'failed',
        executed: false,
        requires_confirmation: false,
        result_summary: { error_code: errorCode, ...(partialData.partial ? { partial: true } : {}) },
        error_code: errorCode,
        duration_ms: Date.now() - startedMs,
        received_at: ctx.received_at,
      },
      response,
    },
  }];
}

// Detect HTTP/node errors
if (executorItem.error || executorItem.statusCode >= 400) {
  const msg = String(executorItem.error?.message || executorItem.message || 'Executor falhou');
  if (/timeout/i.test(msg)) return fail('EXECUTOR_TIMEOUT', 'Timeout do executor.');
  return fail('EXECUTOR_FAILED', 'Falha ao consultar serviço especializado.', { partial: true });
}

let data = {};
let partial = false;

try {
  if (action === 'system.status') {
    const cpu = executorItem.cpu || {};
    const memory = executorItem.memory || {};
    data = {
      cpu: {
        usage_percent: cpu.usage_percent ?? null,
        load_1m: cpu.load_1m ?? null,
        load_5m: cpu.load_5m ?? null,
        load_15m: cpu.load_15m ?? null,
      },
      memory: {
        used_percent: memory.used_percent ?? null,
        used_bytes: memory.used_bytes ?? null,
        total_bytes: memory.total_bytes ?? null,
        available_bytes: memory.available_bytes ?? null,
      },
      uptime_seconds: executorItem.uptime_seconds ?? null,
      uptime_human: executorItem.uptime_human ?? null,
    };
  } else if (action === 'storage.status') {
    data = {
      healthy: !!executorItem.healthy,
      mounted: !!executorItem.mounted,
      rw: String(executorItem.mode || '') === 'rw',
      identity_match: !!executorItem.identity_match,
      read_test: !!executorItem.read_test,
    };
  } else if (action === 'backup.status') {
    const pg = executorItem.postgres || {};
    const entries = Object.values(pg);
    const ok = entries.filter((e) => e && e.status === 'ok').length;
    const failCount = entries.filter((e) => e && e.status && e.status !== 'ok').length;
    const restic = executorItem.restic || {};
    const offsite = executorItem.offsite || {};
    data = {
      healthy: !!executorItem.healthy,
      checked_at: executorItem.checked_at ?? null,
      postgres: { configured: entries.length, ok, failed: failCount },
      restic: {
        status: restic.status ?? null,
        age_hours: restic.age_hours ?? null,
        last_result: restic.last_result ?? null,
        snapshot_count: restic.snapshot_count ?? null,
      },
      offsite: {
        status: offsite.status ?? null,
        age_hours: offsite.age_hours ?? null,
      },
      issues_count: Array.isArray(executorItem.issues) ? executorItem.issues.length : 0,
    };
  } else if (action === 'docker.status') {
    const containers = Array.isArray(executorItem.containers) ? executorItem.containers : [];
    data = {
      healthy: !!executorItem.healthy,
      summary: {
        total: executorItem.summary?.total ?? containers.length,
        running: executorItem.summary?.running ?? null,
        stopped: executorItem.summary?.stopped ?? null,
        unhealthy: executorItem.summary?.unhealthy ?? null,
      },
      containers: containers.map((c) => ({
        name: c.name ?? null,
        state: c.state ?? null,
        health: c.health ?? null,
      })),
    };
  } else if (action === 'disk.status') {
    const filesystems = Array.isArray(executorItem.filesystems) ? executorItem.filesystems : [];
    data = {
      status: executorItem.status ?? null,
      summary: executorItem.summary || {},
      mounts: filesystems.map((f) => ({
        mount: f.mount ?? null,
        used_percent: f.used_percent ?? null,
        capacity_state: f.capacity_state ?? null,
        available: f.available ?? null,
        total_gb: f.total_gb ?? null,
        free_gb: f.free_gb ?? null,
      })),
    };
  } else if (action === 'immich.status') {
    // From immich_monitor_state row
    if (!executorItem.overall_status && executorItem.overall_status !== 'healthy') {
      // empty row
      if (executorItem.overall_status == null && Object.keys(executorItem).length === 0) {
        partial = true;
        data = { overall: 'unknown', assets_count: null, jobs: {}, ml: null, problems: [], partial: true };
      } else {
        let problems = executorItem.problems || [];
        if (typeof problems === 'string') {
          try { problems = JSON.parse(problems); } catch (e) { problems = []; }
        }
        data = {
          overall: executorItem.overall_status ?? 'unknown',
          assets_count: executorItem.asset_count ?? null,
          jobs: {
            backlog_total: executorItem.backlog_total ?? null,
          },
          ml: executorItem.ml_status ?? null,
          storage_accessible: executorItem.storage_accessible ?? null,
          problems: (problems || []).map((p) => ({
            code: p.code ?? p.event ?? null,
            severity: p.severity ?? null,
          })),
          checked_at: executorItem.timestamp ?? executorItem.checked_at ?? null,
        };
      }
    } else {
      let problems = executorItem.problems || [];
      if (typeof problems === 'string') {
        try { problems = JSON.parse(problems); } catch (e) { problems = []; }
      }
      data = {
        overall: executorItem.overall_status ?? 'unknown',
        assets_count: executorItem.asset_count ?? null,
        jobs: {
          backlog_total: executorItem.backlog_total ?? null,
        },
        ml: executorItem.ml_status ?? null,
        storage_accessible: executorItem.storage_accessible ?? null,
        problems: (problems || []).map((p) => ({
          code: p.code ?? p.event ?? null,
          severity: p.severity ?? null,
        })),
        checked_at: executorItem.timestamp ?? null,
      };
    }
  } else if (action === 'rag.stats') {
    data = {
      documents: executorItem.documents ?? null,
      chunks: executorItem.chunks ?? null,
      model: executorItem.embedding_model ?? null,
      dimension: executorItem.vector_dimension ?? null,
    };
  } else if (action === 'audiobook.stats') {
    const by = executorItem.by_status || {};
    data = {
      jobs: executorItem.total_jobs ?? null,
      completed: by.completed ?? 0,
      processing: (by.processing ?? 0) + (by.received ?? 0) + (executorItem.worker_busy ? 1 : 0),
      failed: by.failed ?? 0,
    };
  } else if (action === 'media.stats') {
    data = {
      total_items: executorItem.total_items ?? null,
      by_status: executorItem.by_status || {},
      worker_busy: !!executorItem.worker_busy,
    };
  } else {
    return fail('ACTION_NOT_ALLOWED', 'Executor sem sanitizer.');
  }
} catch (e) {
  return fail('EXECUTOR_FAILED', 'Falha ao sanitizar resultado.', { partial: true });
}

if (partial) data.partial = true;

const finished = new Date().toISOString();
const response = {
  request_id: requestId,
  action,
  status: 'success',
  executed: true,
  requires_confirmation: false,
  message: 'ok',
  data,
  started_at: new Date(startedMs).toISOString(),
  finished_at: finished,
};

return [{
  json: {
    http_status: 200,
    security_event: false,
    audit: {
      request_id: requestId,
      requested_at: ctx.requested_at,
      requested_by: ctx.requested_by,
      action,
      risk: ctx.risk || 'READ',
      parameters: {},
      status: 'success',
      executed: true,
      requires_confirmation: false,
      result_summary: {
        keys: Object.keys(data),
